package app.kinnect.audit;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;import java.io.*;import org.json.*;import org.webrtc.PeerConnectionFactory;
public class PlayPolicyAudit extends Instrumentation {
 private static void field(Activity a,String name,Object value)throws Exception{Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);f.set(a,value);}
 private static Object call(Activity a,String name,Class<?>[] types,Object...args)throws Exception{Method m=a.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(a,args);}
 private static String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString()+"\n":"";if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)s+=text(g.getChildAt(i));}return s;}
 private static void require(String value,String needle){if(!value.contains(needle))throw new AssertionError("Missing UI text: "+needle);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{
  Class<?> language=getTargetContext().getClassLoader().loadClass("app.kinnect.live.I18n");Method select=language.getDeclaredMethod("select",Context.class,String.class);select.setAccessible(true);select.invoke(null,getTargetContext(),"vi");
  Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1300);
  if(a.getApplicationInfo().targetSdkVersion!=36)throw new AssertionError("Target is not API 36");if((a.getApplicationInfo().flags&ApplicationInfo.FLAG_DEBUGGABLE)!=0)throw new AssertionError("Release is debuggable");
  PackageInfo info=a.getPackageManager().getPackageInfo(a.getPackageName(),PackageManager.GET_PERMISSIONS);for(String permission:info.requestedPermissions)if(permission.endsWith("REQUEST_INSTALL_PACKAGES")||permission.endsWith("READ_MEDIA_IMAGES")||permission.endsWith("READ_MEDIA_VIDEO")||permission.endsWith("REQUEST_IGNORE_BATTERY_OPTIMIZATIONS"))throw new AssertionError("Forbidden Play permission: "+permission);
  try{a.getClassLoader().loadClass("app.kinnect.live.ApkUpdateActivity");throw new AssertionError("External APK installer present");}catch(ClassNotFoundException expected){}
  if(!a.getClassLoader().loadClass("app.kinnect.live.Distribution").getField("PLAY").getBoolean(null))throw new AssertionError("Not the Play distribution");
  for(String asset:new String[]{"welcome-profile.png","welcome-profile-1.png","welcome-profile-2.png","welcome-profile-3.png"})try(InputStream stream=a.getAssets().open(asset)){if(BitmapFactory.decodeStream(stream)==null)throw new AssertionError("Broken onboarding image");}
  PeerConnectionFactory.initialize(PeerConnectionFactory.InitializationOptions.builder(a).setEnableInternalTracer(false).createInitializationOptions());PeerConnectionFactory factory=PeerConnectionFactory.builder().createPeerConnectionFactory();factory.dispose();
  runOnMainSync(()->{try{field(a,"me",new JSONObject().put("id","policy-local").put("name","Kiểm tra bản Google Play").put("username","policy_audit").put("dmMode","everyone"));call(a,"settings",new Class[]{});String shown=text(a.getWindow().getDecorView());require(shown,"Xóa tài khoản và dữ liệu");require(shown,"Đồng bộ tin nhắn nền");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();shot(a,"play-settings.png");
  final Dialog[] consent=new Dialog[1];runOnMainSync(()->{try{Class<?> cls=a.getClassLoader().loadClass("app.kinnect.live.Sheet");Constructor<?> constructor=cls.getDeclaredConstructor(android.content.Context.class);constructor.setAccessible(true);Object sheet=constructor.newInstance(a);Method message=cls.getDeclaredMethod("setMessage",CharSequence.class),positive=cls.getDeclaredMethod("setPositiveButton",CharSequence.class,android.content.DialogInterface.OnClickListener.class),show=cls.getDeclaredMethod("show");message.setAccessible(true);positive.setAccessible(true);show.setAccessible(true);StringBuilder notice=new StringBuilder();for(int i=0;i<12;i++)notice.append("Kinnect sử dụng Cloudflare/NVIDIA để hỗ trợ kiểm duyệt. Bạn có quyền xóa tài khoản và dữ liệu. ");message.invoke(sheet,notice.toString());positive.invoke(sheet,"Tôi đồng ý",null);consent[0]=(Dialog)show.invoke(sheet);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();runOnMainSync(()->{ScrollView outer=findScroll(consent[0].getWindow().getDecorView());if(outer==null)throw new AssertionError("Long consent cannot scroll");outer.fullScroll(View.FOCUS_DOWN);});waitForIdleSync();Thread.sleep(200);runOnMainSync(()->{TextView button=findText(consent[0].getWindow().getDecorView(),"Tôi đồng ý");android.graphics.Rect rect=new android.graphics.Rect();if(button==null||!button.getGlobalVisibleRect(rect)||rect.height()<1)throw new AssertionError("Cannot reach consent action");});shot(a,"play-consent-long.png");runOnMainSync(()->consent[0].dismiss());
  for(String policy:new String[]{"privacy","community","child-safety"}){runOnMainSync(()->{try{call(a,"nativeDocument",new Class[]{String.class,Runnable.class},policy,(Runnable)()->{});String shown=text(a.getWindow().getDecorView());require(shown,"anhvn53@wru.vn");if(policy.equals("privacy")){require(shown,"Cloudflare");require(shown,"NVIDIA");require(shown,"xóa tài khoản");if(shown.contains("Chưa có công cụ tự phục vụ"))throw new AssertionError("Stale privacy policy");}if(policy.equals("child-safety"))require(shown,"CSAE");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();shot(a,"play-"+policy+".png");}
  runOnMainSync(()->{try{call(a,"deleteAccountScreen",new Class[]{});String shown=text(a.getWindow().getDecorView());require(shown,"Xóa vĩnh viễn tài khoản và dữ liệu");require(shown,"Không thể khôi phục");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();shot(a,"play-delete-account.png");
  result.putString("result","PASS: API36 release, no external installer/broad-media permissions, canonical policy/deletion/settings UI, all intro assets decode, WebRTC native factory loads on the device");finish(Activity.RESULT_OK,result);
 }catch(Throwable t){result.putString("error",t.toString());finish(Activity.RESULT_CANCELED,result);}}
 private static ScrollView findScroll(View v){if(v instanceof ScrollView)return (ScrollView)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){ScrollView found=findScroll(g.getChildAt(i));if(found!=null)return found;}}return null;}
 private static TextView findText(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return (TextView)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView found=findText(g.getChildAt(i),text);if(found!=null)return found;}}return null;}
 private void shot(Activity a,String name)throws Exception{File f=new File(a.getExternalFilesDir(null),name);try(FileOutputStream out=new FileOutputStream(f)){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}}
}
